/**
 * Lightweight Standalone PKZIP Builder (Offline JSZip implementation)
 * Supports zip.file(name, data, {base64: true|false}) and zip.generateAsync({type: 'blob'})
 */
(function (window) {
  'use strict';

  function SimpleZip() {
    this.files = [];
  }

  SimpleZip.prototype.file = function (filename, data, options) {
    options = options || {};
    let bytes;

    if (data instanceof Blob) {
      this.files.push({ name: filename, blob: data });
      return this;
    }

    if (options.base64 && typeof data === 'string') {
      const binaryString = atob(data);
      bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
    } else if (typeof data === 'string') {
      const encoder = new TextEncoder();
      bytes = encoder.encode(data);
    } else if (data instanceof Uint8Array) {
      bytes = data;
    } else if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    }

    this.files.push({ name: filename, data: bytes });
    return this;
  };

  // CRC32 table
  const crcTable = (function () {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) {
        c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
      }
      table[i] = c;
    }
    return table;
  })();

  function crc32(buf) {
    let crc = 0 ^ (-1);
    for (let i = 0; i < buf.length; i++) {
      crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  SimpleZip.prototype.generateAsync = function (options) {
    const self = this;
    return new Promise(function (resolve) {
      // Resolve any blob files first
      const resolvePromises = self.files.map(function (f) {
        if (f.blob) {
          return new Promise(function (res) {
            const reader = new FileReader();
            reader.onload = function (e) {
              f.data = new Uint8Array(e.target.result);
              delete f.blob;
              res();
            };
            reader.readAsArrayBuffer(f.blob);
          });
        }
        return Promise.resolve();
      });

      Promise.all(resolvePromises).then(function () {
        const parts = [];
        const cdHeaders = [];
        let offset = 0;

        for (let i = 0; i < self.files.length; i++) {
          const file = self.files[i];
          const nameBytes = new TextEncoder().encode(file.name);
          const dataBytes = file.data || new Uint8Array(0);
          const crc = crc32(dataBytes);
          const size = dataBytes.length;

          // Local file header (30 bytes + filename)
          const localHeader = new Uint8Array(30 + nameBytes.length);
          const lv = new DataView(localHeader.buffer);

          lv.setUint32(0, 0x04034b50, true); // Local file header signature
          lv.setUint16(4, 20, true);         // Version needed to extract (2.0)
          lv.setUint16(6, 0, true);          // General purpose bit flag
          lv.setUint16(8, 0, true);          // Compression method (0 = store)
          lv.setUint16(10, 0, true);         // Last mod file time
          lv.setUint16(12, 0, true);         // Last mod file date
          lv.setUint32(14, crc, true);       // CRC-32
          lv.setUint32(18, size, true);      // Compressed size
          lv.setUint32(22, size, true);      // Uncompressed size
          lv.setUint16(26, nameBytes.length, true); // Filename length
          lv.setUint16(28, 0, true);         // Extra field length
          localHeader.set(nameBytes, 30);

          parts.push(localHeader);
          parts.push(dataBytes);

          // Central directory header (46 bytes + filename)
          const cdHeader = new Uint8Array(46 + nameBytes.length);
          const cv = new DataView(cdHeader.buffer);

          cv.setUint32(0, 0x02014b50, true); // Central directory signature
          cv.setUint16(4, 20, true);         // Version made by
          cv.setUint16(6, 20, true);         // Version needed to extract
          cv.setUint16(8, 0, true);          // General purpose bit flag
          cv.setUint16(10, 0, true);         // Compression method (0 = store)
          cv.setUint16(12, 0, true);         // Last mod file time
          cv.setUint16(14, 0, true);         // Last mod file date
          cv.setUint32(16, crc, true);       // CRC-32
          cv.setUint32(20, size, true);      // Compressed size
          cv.setUint32(24, size, true);      // Uncompressed size
          cv.setUint16(28, nameBytes.length, true); // Filename length
          cv.setUint16(30, 0, true);         // Extra field length
          cv.setUint16(32, 0, true);         // File comment length
          cv.setUint16(34, 0, true);         // Disk number start
          cv.setUint16(36, 0, true);         // Internal file attributes
          cv.setUint32(38, 0, true);         // External file attributes
          cv.setUint32(42, offset, true);    // Relative offset of local header
          cdHeader.set(nameBytes, 46);

          cdHeaders.push(cdHeader);
          offset += localHeader.length + dataBytes.length;
        }

        const cdOffset = offset;
        let cdSize = 0;
        for (let i = 0; i < cdHeaders.length; i++) {
          parts.push(cdHeaders[i]);
          cdSize += cdHeaders[i].length;
        }

        // End of central directory record (22 bytes)
        const eocd = new Uint8Array(22);
        const ev = new DataView(eocd.buffer);
        ev.setUint32(0, 0x06054b50, true); // End of central dir signature
        ev.setUint16(4, 0, true);          // Number of this disk
        ev.setUint16(6, 0, true);          // Number of disk with start of CD
        ev.setUint16(8, self.files.length, true);  // Total entries on this disk
        ev.setUint16(10, self.files.length, true); // Total entries in CD
        ev.setUint32(12, cdSize, true);    // Size of central directory
        ev.setUint32(16, cdOffset, true);  // Offset of start of CD
        ev.setUint16(20, 0, true);         // Comment length

        parts.push(eocd);

        const blob = new Blob(parts, { type: 'application/zip' });
        resolve(blob);
      });
    });
  };

  window.JSZip = SimpleZip;
})(window);
